<script defer src="../public/js/nursync-ui.js?v=4"></script></head><body class="module-ui"><?php include '../includes/employee_documents_sidebar.php';?><main class="ed-expiring-main"><header class="page-head attendance-list-head"><div><h1><i class="fa-solid fa-calendar-check"></i> Attendance &amp; Leave Master List</h1><p>Read-only employee lateness and leave usage totals.</p></div><div class="head-controls"><?php if($canMarkResigned):?><button class="btn green" type="button" onclick="document.getElementById('encodeAttendanceModal').showModal()"><i class="fa-solid fa-plus"></i> Encode Attendance / Leave</button><?php endif;?><form class="period-filter" method="get"><input type="hidden" name="view" value="attendance_leave"><label>Year<input type="number" name="year" min="2000" max="2100" value="<?=$leaveYear?>"></label><label>Month<select name="month"><option value="0">All Months</option><?php for($month=1;$month<=12;$month++):?><option value="<?=$month?>" <?=$leaveMonth===$month?'selected':''?>><?=date('F',mktime(0,0,0,$month,1))?></option><?php endfor;?></select></label><button class="btn" type="submit"><i class="fa-solid fa-filter"></i> Apply</button></form></div></header><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=h($success)?></div><?php endif;?>
<section class="panel"><p class="summary-period"><strong>Showing:</strong> <?=$leaveMonth?date('F',mktime(0,0,0,$leaveMonth,1)).' ':''?><?=$leaveYear?></p><div class="table-wrap"><table class="table summary-table"><thead><tr><th>Employee ID</th><th>Employee</th><th>Department</th><th>Late Count</th><th>Late Minutes</th><th>VL Used</th><th>SL Used</th><th>SPL Used</th><th>Wellness Used</th><th>Calamity Used</th></tr></thead><tbody><?php foreach($employees as$employee):$summary=$leaveSummaries[(int)$employee['user_id']]??[];?><tr><td><?=h($employee['employee_id']?:$employee['user_id'])?></td><td><strong><?=h($employee['name'])?></strong><br><small><?=h($employee['position']?:str_replace('_',' ',$employee['role']))?></small></td><td><?=h(str_replace('_',' ',$employee['department']??''))?></td><td><span class="count-value"><?=(int)($summary['late_count']??0)?></span></td><td><span class="count-value"><?=(int)($summary['late_minutes_total']??0)?></span></td><td><span class="leave-value"><?=number_format((float)($summary['vacation_leave_used']??0),2)?></span></td><td><span class="leave-value"><?=number_format((float)($summary['sick_leave_used']??0),2)?></span></td><td><span class="leave-value"><?=number_format((float)($summary['special_privilege_leave_used']??0),2)?></span></td><td><span class="leave-value"><?=number_format((float)($summary['wellness_leave_used']??0),2)?></span></td><td><span class="leave-value"><?=number_format((float)($summary['calamity_leave_used']??0),2)?></span></td></tr><?php endforeach;?><?php if(!$employees):?><tr><td colspan="10" class="empty">No active employees found.</td></tr><?php endif;?></tbody></table></div></section></main>
<?php if($canMarkResigned):?><dialog class="encode-modal" id="encodeAttendanceModal"><div class="encode-modal-head"><div><h2>Encode Attendance / Leave</h2><p>Select whether you are recording a late arrival or leave.</p></div><button class="modal-x" type="button" onclick="this.closest('dialog').close()">×</button></div><form class="encode-form" method="post" id="encodeAttendanceForm"><?=csrfField()?><input type="hidden" name="action" value="save_attendance_record"><input type="hidden" name="return_view" value="attendance_leave"><div class="encode-grid"><label>Employee *<input type="search" id="employeeLookup" list="employeeList" placeholder="Search employee name, ID, or department" autocomplete="off" required><input type="hidden" name="employee_id" id="employeeValue"><datalist id="employeeList"><?php foreach($employees as$employee):$label=$employee['name'].' — '.($employee['employee_id']?:$employee['user_id']).' — '.str_replace('_',' ',$employee['department']??'');?><option value="<?=h($label)?>" data-id="<?=$employee['user_id']?>"></option><?php endforeach;?></datalist></label><label>What will you encode? *<select name="record_type" id="recordType" required><option value="">Select record type</option><option value="LATE">Late</option><option value="LEAVE">Leave</option></select></label><label>Record Date *<input type="date" name="record_date" max="<?=date('Y-m-d')?>" value="<?=date('Y-m-d')?>" required></label><label class="encode-field late-field" hidden>Duty Schedule *<select name="duty_schedule" id="dutySchedule"><option value="">Select schedule</option><option value="06:00-18:00">6:00 AM – 6:00 PM</option><option value="18:00-06:00">6:00 PM – 6:00 AM</option><option value="06:00-14:00">6:00 AM – 2:00 PM</option><option value="14:00-22:00">2:00 PM – 10:00 PM</option><option value="22:00-06:00">10:00 PM – 6:00 AM</option><option value="07:00-18:00">7:00 AM – 6:00 PM</option><option value="08:00-17:00">8:00 AM – 5:00 PM</option></select></label><label class="encode-field late-field" hidden>Actual Time In *<input type="time" name="actual_time_in" id="actualTime"></label><label class="encode-field late-field" hidden>Calculated Late Minutes<div class="late-result" id="lateResult">0 min</div></label><label class="encode-field leave-field" hidden>Type of Leave *<select name="leave_type" id="leaveType"><option value="">Select leave type</option><option>VACATION LEAVE</option><option>SICK LEAVE</option><option>SPECIAL PRIVILEGE LEAVE</option><option>WELLNESS LEAVE</option><option>CALAMITY LEAVE</option></select></label><label class="wide">Remarks<textarea name="remarks" rows="3" maxlength="255" placeholder="Optional remarks"></textarea></label></div><div class="modal-actions"><button class="btn light" type="button" onclick="this.closest('dialog').close()">Cancel</button><button class="btn green" type="submit"><i class="fa-solid fa-floppy-disk"></i> Save Record</button></div></form></dialog><script>(()=>{const dialog=document.getElementById('encodeAttendanceModal'),form=document.getElementById('encodeAttendanceForm'),lookup=document.getElementById('employeeLookup'),employeeValue=document.getElementById('employeeValue'),employeeMap=new Map([...document.querySelectorAll('#employeeList option')].map(option=>[option.value,option.dataset.id])),type=document.getElementById('recordType'),schedule=document.getElementById('dutySchedule'),actual=document.getElementById('actualTime'),leave=document.getElementById('leaveType'),result=document.getElementById('lateResult'),lateFields=[...document.querySelectorAll('.late-field')],leaveFields=[...document.querySelectorAll('.leave-field')];function validateEmployee(){employeeValue.value=employeeMap.get(lookup.value)||'';lookup.setCustomValidity(employeeValue.value?'':'Please select an employee from the dropdown.')}function updateType(){const late=type.value==='LATE',onLeave=type.value==='LEAVE';lateFields.forEach(field=>field.hidden=!late);leaveFields.forEach(field=>field.hidden=!onLeave);schedule.required=late;actual.required=late;leave.required=onLeave;if(!late){schedule.value='';actual.value='';result.textContent='0 min';result.classList.remove('late')}if(!onLeave)leave.value=''}function calculate(){if(!schedule.value||!actual.value){result.textContent='0 min';return}const start=schedule.value.slice(0,5).split(':').map(Number),time=actual.value.split(':').map(Number),minutes=Math.max(0,time[0]*60+time[1]-start[0]*60-start[1]);result.textContent=minutes+' min';result.classList.toggle('late',minutes>0)}lookup.addEventListener('input',validateEmployee);lookup.addEventListener('change',validateEmployee);type.addEventListener('change',updateType);schedule.addEventListener('change',calculate);actual.addEventListener('input',calculate);form.addEventListener('submit',validateEmployee);dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});dialog.addEventListener('cancel',event=>{event.preventDefault();dialog.close()});updateType()})();</script><?php endif;?></body></html>
